"""GiftBooks Illinois Library Checker

Single-file, local-first book checker for Apple Silicon.

Purpose:
    Photograph a book, extract only the identifiers needed for searching, and
    report whether the same book/edition appears in the Illinois Library Catalog.

Install:
    python3.11 -m venv .venv
    source .venv/bin/activate
    pip install -U flask requests mlx-vlm pydantic Pillow pillow-heif openpyxl

Run:
    python giftbooks_local_v2.py

The vision model runs locally. Searching the Illinois Library Catalog requires internet
access. Browser speech-recognition behavior depends on the browser and may use
an online speech service.
"""

